var q = new BoundedBlockingQueue<int>(4);
long produced = 0, consumed = 0; int consumedCount = 0;
var producers = new List<Task>();
for (int p = 0; p < 4; p++)
    producers.Add(Task.Run(() => { for (int i = 1; i <= 5000; i++) { q.Enqueue(i); Interlocked.Add(ref produced, i); } }));
var consumers = new List<Task>();
for (int c = 0; c < 4; c++)
    consumers.Add(Task.Run(() => { while (q.TryDequeue(out var x)) { Interlocked.Add(ref consumed, x); Interlocked.Increment(ref consumedCount); } }));
T.True("producers finished (no deadlock)", Task.WaitAll(producers.ToArray(), 8000));
q.Complete();
T.True("consumers exit after Complete", Task.WaitAll(consumers.ToArray(), 5000));
T.Eq("nothing lost or duplicated (sum)", Interlocked.Read(ref consumed), Interlocked.Read(ref produced));
T.Eq("nothing lost or duplicated (count)", consumedCount, 20000);

