using var cts = new CancellationTokenSource(100);
var sw = System.Diagnostics.Stopwatch.StartNew();
T.Throws<OperationCanceledException>("blocked producer honours cancellation", () => full.Enqueue(2, cts.Token));
T.True("promptly", sw.ElapsedMilliseconds < 1500);
